 await check('Read pagination preserves hashes and reports accurate ranges for long lines',async()=>{const target=path.join(root,'paged.txt');fs.writeFileSync(target,'abcdefghij\nklmno\npqrstuvwxyz');const tools=require(core+'/revival-assistant-tools.cjs').create({files:require(core+'/revival-assistant-files.cjs').create()}),run={session:store.conversation(root),abort:new AbortController(),readLimit:6};let args={path:target},last,rebuilt='',digest;for(let n=0;n<20;n++){const read=await tools.execute(call('read_file',args),run);digest??=read.sha256;assert.equal(read.sha256,digest);assert(read.content.length<=6);if(last&&read.start_line>last.end_line&&!rebuilt.endsWith('\n'))rebuilt+='\n';rebuilt+=read.content;last=read;if(!read.next_read)break;args=read.next_read;}assert.equal(rebuilt,fs.readFileSync(target,'utf8'));assert.equal(last.end_line,3);assert.equal(last.end_column,11);await assert.rejects(tools.execute(call('read_file',{path:target,start_line:100}),run),/Invalid file range/);});
